const prefixes = [];
const denied = new Set(["apply_patch","update_plan","view_image","web_search","Bash","write_stdin","list_mcp_resources","list_mcp_resource_templates","read_mcp_resource","request_user_input","spawn_agent","send_input","wait_agent","close_agent","resume_agent","imagegen","tool_search","get_goal","create_goal","update_goal","web","exec","wait","send_message","followup_task","interrupt_agent","list_agents","request_permissions","sleep","current_time","get_context_remaining","new_context","wait_for_environment","list_available_plugins_to_install","request_plugin_install","create_channel","get_channels","list_threads","post","read_post","read_thread","search_posts","subscribe","unsubscribe"]);
const native = new Set([]);
let data = '';
process.stdin.on('data', chunk => { data += chunk; });
process.stdin.on('end', () => {
  let allowed = false;
  try {
    const input = JSON.parse(data);
    allowed = typeof input.tool_name === 'string' && (native.has(input.tool_name) || prefixes.some(prefix => input.tool_name.startsWith(prefix) && input.tool_name.length > prefix.length)) && !denied.has(input.tool_name);
